(()=>{const el=id=>document.getElementById(id),n=id=>Number(el(id).value)||0,fmt=(x,d=0)=>new Intl.NumberFormat('en-IE',{maximumFractionDigits:d}).format(x),eur=x=>'€'+fmt(x),defaults={'roi-unit-cost':6495,'roi-install':1000,'roi-support':1440,'roi-discount':10};function render(){const units=n('calc-labs')*n('calc-hplc-count'),volume=units*n('calc-flow')*60*n('calc-hours-day')*n('calc-days-week')*n('calc-weeks-year')/1000,equipment=units*n('roi-unit-cost'),install=units*n('roi-install'),upfront=equipment+install,support=units*n('roi-support'),gross=volume*(n('calc-recovery')/100*n('calc-solvent-cost')+n('calc-waste-reduction')/100*n('calc-disposal-cost')),net=gross-support,r=n('roi-discount')/100;el('roi-support-total').textContent=eur(n('roi-support'))+'/year';Object.keys(defaults).forEach(id=>el(id+'-output').textContent=fmt(n(id),id==='roi-discount'?1:0)+(id==='roi-discount'?'%':id==='roi-support'?' €/unit/year':' €/unit'));el('roi-units-note').textContent=fmt(units)+' units · '+eur(upfront)+' upfront · '+eur(support)+' support and maintenance per year. NPV uses '+fmt(r*100,1)+'% annual discounting.';for(const years of [1,3]){const benefit=net*years-upfront,npv=-upfront+Array.from({length:years},(_,i)=>net/Math.pow(1+r,i+1)).reduce((a,b)=>a+b,0),vals={equipment:eur(equipment)+' once',install:eur(install)+' once',upfront:eur(upfront)+' once',support:eur(support*years),net:eur(net*years),benefit:eur(benefit),payback:upfront===0?'No upfront investment':net>0?fmt(upfront/net*12,1)+' months':'No payback at these inputs',roi:upfront>0?fmt(benefit/upfront*100,1)+'%':'N/A · zero upfront investment',npv:eur(npv)};for(const[k,v]of Object.entries(vals))document.querySelector('[data-roi="'+k+'-'+years+'"]').textContent=v;}}Object.keys(defaults).forEach(id=>el(id).addEventListener('input',render));document.addEventListener('resolve-model',render);el('calc-reset').addEventListener('click',()=>{Object.entries(defaults).forEach(([id,v])=>el(id).value=v);render();});render();})();